// Builds src/data/landDots.ts: the land of the world map as a grid of dots.
//
// Source data: Natural Earth 1:110m land (public domain, https://www.naturalearthdata.com),
// as TopoJSON in the world-atlas npm package (land-110m.json, ISC license).
// world-atlas is a devDependency used only by this script. The runtime bundle
// imports the generated file and has no map dependency.
//
// Run from dashboard/:  node scripts/build-land-dots.mjs
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'

const require = createRequire(import.meta.url)
const STEP = 2 // degrees between dots
const LAT_MAX = 84 // the map shows 84° N to 58° S (no Antarctica)
const LAT_MIN = -58
const OUT = new URL('../src/data/landDots.ts', import.meta.url)

const topology = JSON.parse(readFileSync(require.resolve('world-atlas/land-110m.json'), 'utf8'))
const { scale, translate } = topology.transform

// Decode the quantized, delta-encoded arcs to [lon, lat] points.
const arcs = topology.arcs.map((arc) => {
  let x = 0
  let y = 0
  return arc.map(([dx, dy]) => {
    x += dx
    y += dy
    return [x * scale[0] + translate[0], y * scale[1] + translate[1]]
  })
})

function ring(indexes) {
  const points = []
  for (const index of indexes) {
    const arc = index < 0 ? arcs[~index].slice().reverse() : arcs[index]
    points.push(...(points.length ? arc.slice(1) : arc))
  }
  return points
}

// Every polygon as a list of rings (outer ring and holes).
const polygons = []
for (const geometry of topology.objects.land.geometries) {
  const list = geometry.type === 'Polygon' ? [geometry.arcs] : geometry.arcs
  for (const polygon of list) {
    polygons.push(polygon.map(ring))
  }
}

// Even-odd rule over all rings of a polygon, so holes stay empty.
function inside([lon, lat], rings) {
  let result = false
  for (const points of rings) {
    for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
      const [xi, yi] = points[i]
      const [xj, yj] = points[j]
      if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
        result = !result
      }
    }
  }
  return result
}

const isLand = (point) => polygons.some((rings) => inside(point, rings))

// One row per latitude: [lat, from, to, from, to, ...], runs of land dots in longitude.
const rows = []
let count = 0
for (let lat = LAT_MAX - STEP / 2; lat >= LAT_MIN; lat -= STEP) {
  const row = [lat]
  let runStart = null
  let previous = null
  for (let lon = -180 + STEP / 2; lon < 180; lon += STEP) {
    if (isLand([lon, lat])) {
      count += 1
      if (runStart === null) runStart = lon
      previous = lon
    } else if (runStart !== null) {
      row.push(runStart, previous)
      runStart = null
    }
  }
  if (runStart !== null) row.push(runStart, previous)
  if (row.length > 1) rows.push(row)
}

const body = rows.map((row) => `  [${row.join(', ')}],`).join('\n')
writeFileSync(
  OUT,
  `// Generated by scripts/build-land-dots.mjs. Do not edit by hand.
// Source: Natural Earth 1:110m land (public domain), from world-atlas@2.0.2 land-110m.json (ISC).
// ${count} land dots on a ${STEP}° grid, from ${LAT_MAX}° N to ${Math.abs(LAT_MIN)}° S.

export const LAND_STEP = ${STEP}
export const LAND_LAT_MAX = ${LAT_MAX}
export const LAND_LAT_MIN = ${LAT_MIN}

// One row per latitude: [lat, lonFrom, lonTo, lonFrom, lonTo, ...]. Each pair is a run of
// land dots, ${STEP}° apart, from lonFrom to lonTo inclusive.
export const LAND_ROWS: number[][] = [
${body}
]
`,
)
console.log(`wrote ${count} dots in ${rows.length} rows to ${OUT.pathname}`)
